import { NextFunction, Request, Response } from 'express';
import { CreateProjectUseCase } from '../../application/use-cases/CreateProjectUseCase';
import { RequestParser } from '../http/RequestParser';

export class ProjectController {
  constructor(private readonly createProject: CreateProjectUseCase) {}

  create = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const body = new RequestParser(req.body, 'Body');
      const project = await this.createProject.execute({ name: body.requiredString('name') });
      res.status(201).json(project);
    } catch (error) {
      next(error);
    }
  };
}

